result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/nernst.py", "content": """"Electrochemistry toolkit: Nernst equation and equilibrium constants."""

import math

R = 8.314      # Gas constant, J/(mol*K)
F = 96485.0    # Faraday constant, C/mol
T_DEFAULT = 298.15  # Standard temperature, K


def nernst(e0, n, q, t=T_DEFAULT):
    """Cell potential E = E0 - (R*T/(n*F)) * ln(Q).

    e0 : standard cell potential (V)
    n  : number of electrons transferred
    q  : reaction quotient
    t  : temperature in K (default 298.15)
    """
    if n <= 0:
        raise ValueError("n must be positive")
    if q <= 0:
        raise ValueError("Q must be positive")
    return e0 - (R * t / (n * F)) * math.log(q)


def log_equilibrium_constant(e0, n, t=T_DEFAULT):
    """log10(K) = n*F*E0 / (R*T*ln(10))."""
    if n <= 0:
        raise ValueError("n must be positive")
    return n * F * e0 / (R * t * math.log(10))


def concentration_cell_potential(ratio, n, t=T_DEFAULT):
    """Potential of a concentration cell (E0 = 0).

    ratio : quotient Q = [dilute species]/[concentrated species] scale factor
            (use >1 for the spontaneous direction).
    """
    return nernst(0.0, n, ratio, t)
